    result = []
    for item in lst:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def remove_duplicates(lst):
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def roman_to_int(s: str) -> int:
    rom_val = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    new_s = s.replace('IV', 'IIII').replace('IX', 'VIII')
    new_s = new_s.replace('XL', 'XXXX').replace('XC', 'LXXX')
    new_s = new_s.replace('CD', 'CCCC').replace('CM', 'DCCC')
    num = 0
    for char in new_s:
        num += rom_val[char]
    return num

def is_valid_parens(s: str) -> bool:
    """
    Checks if a string of parentheses is valid.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def count_vowels(s):
    s = s.lower()
    return sum(1 for char in s if char in 'aeiou')

